  'A production-centered study of dramatic literature and script analysis. Students learn to read plays closely for event, action, character, structure, theme, genre, style, given circumstances, and theatrical world. The course links literary analysis to rehearsal-room practice, design choices, dramaturgical research, and persuasive analytical writing.',
  $scajson${"slug": "script-analysis-dramatic-literature", "title": "Script Analysis / Dramatic Literature", "description": "A production-centered study of dramatic literature and script analysis. Students learn to read plays closely for event, action, character, structure, theme, genre, style, given circumstances, and theatrical world. The course links literary analysis to rehearsal-room practice, design choices, dramaturgical research, and persuasive analytical writing.", "topics": [{"id": "1180eb46-e6ec-4b73-8747-62cc614dde51", "type": "topic", "title": "Reading a Play for Production", "description": "This opening unit trains students to read plays as blueprints for live performance, not only as literary texts.", "children": [{"id": "d36d5bb2-9349-443f-a256-d4a45d587177", "type": "subtopic", "title": "First read versus production read", "children": [{"id": "d2def329-87f6-4460-8341-a70fc9bb9aee", "type": "concept", "title": "reader response"}, {"id": "2d8d4d71-1f67-4aa6-87f3-bca3240fda9f", "type": "concept", "title": "questions after first read"}, {"id": "df49ea9a-640d-4e37-87c9-4de736c8c853", "type": "concept", "title": "production clues"}], "description": "Students learn to separate initial audience response from later analytical reading for staging choices."}, {"id": "ab3042fd-4dab-4841-a382-a8ffea00c4f8", "type": "subtopic", "title": "Text as score for action", "children": [{"id": "8dc4c597-86f8-456d-b9fd-204e5bfc3df1", "type": "concept", "title": "speech acts"}, {"id": "940208b0-4f29-420f-9def-ce6c85bf9fe4", "type": "concept", "title": "pauses"}, {"id": "384bc963-f230-47d1-b344-918106a7ce60", "type": "concept", "title": "entrances and exits"}], "description": "The class treats dialogue, silence, stage directions, rhythm, and entrances as playable information."}, {"id": "ebd52f45-021b-4bda-8280-14e137ce23eb", "type": "subtopic", "title": "Production questions", "children": [{"id": "42fdffb7-d671-4b3b-9559-62b5e0d5a8ff", "type": "concept", "title": "actor questions"}, {"id": "ff62c54d-4dac-407b-adc2-014199ae1c65", "type": "concept", "title": "design questions"}, {"id": "15a70581-c507-4d7e-98ba-62a219513d40", "type": "concept", "title": "audience questions"}], "description": "Students practice asking what actors, directors, designers, and dramaturgs need to know from the script."}]}, {"id": "a61ed47d-6764-4829-9b92-4120fbed3f6f", "type": "topic", "title": "Plot and Structure", "description": "Students learn how dramatic events are arranged to shape suspense, revelation, reversal, and audience attention.", "children": [{"id": "36cfa19a-eea5-4231-b9cd-6f3cb4a0c948", "type": "subtopic", "title": "Events and triggers", "children": [{"id": "52790076-5475-4684-bb2f-54be5e01ea10", "type": "concept", "title": "inciting incident"}, {"id": "e2a2f9a8-4332-4678-a37b-608c67f3ac4d", "type": "concept", "title": "trigger and heap"}, {"id": "cd123caa-1237-4010-ac0e-fab51d3f114c", "type": "concept", "title": "major reversals"}], "description": "Students identify what happens, what causes it, and why each event changes the dramatic situation."}, {"id": "540417fc-c2b1-4fe6-98a4-1b6ed62f2199", "type": "subtopic", "title": "Scene and act architecture", "children": [{"id": "54029754-5193-47fe-9bdc-77ce8fa8c706", "type": "concept", "title": "beats"}, {"id": "b190c818-c5d1-44e3-99a2-f7fedcc12c99", "type": "concept", "title": "scene turns"}, {"id": "afdcfd38-7c81-46a6-bc2e-93f5319c43d6", "type": "concept", "title": "act breaks"}], "description": "The class maps beats, scene climaxes, transitions, and larger act movements."}, {"id": "49dfa961-0d0c-4172-ba42-96a9e4e07269", "type": "subtopic", "title": "Alternative structures", "children": [{"id": "c727aabc-7b10-40fd-94d2-3db1c5e7881f", "type": "concept", "title": "nonlinear time"}, {"id": "2cf98a79-65b0-4cf1-a410-26515c69c7e4", "type": "concept", "title": "episodic montage"}, {"id": "fa029760-25c5-423c-a873-649a508aa8d3", "type": "concept", "title": "open endings"}], "description": "Students compare linear, episodic, circular, memory, documentary, and fragmented forms."}]}, {"id": "4d80cfb9-88d3-42e1-b2af-044ed172c779", "type": "topic", "title": "Character Analysis", "description": "This unit builds rigorous methods for understanding characters through action, relationship, contradiction, and social context.", "children": [{"id": "aea06d59-910c-4c01-af36-a8f2fd3dff57", "type": "subtopic", "title": "Objectives and obstacles", "children": [{"id": "ea11d8b3-e19d-4a1b-8bee-a1269a72f8fd", "type": "concept", "title": "superobjective"}, {"id": "41f131f4-c320-4186-a6a8-c1caadc3ee0f", "type": "concept", "title": "scene objective"}, {"id": "baf49881-51c8-490b-81af-92d3c4a4468c", "type": "concept", "title": "tactics"}], "description": "Students connect character behavior to wants, resistance, tactics, and changing stakes."}, {"id": "84301436-8732-4595-ae3f-df4841d72681", "type": "subtopic", "title": "Relationships and status", "children": [{"id": "cbcda7fd-c89e-4d04-9019-c9d69af04479", "type": "concept", "title": "status shifts"}, {"id": "a605de50-8430-4eaa-a7f7-5406c71f0737", "type": "concept", "title": "relationship history"}, {"id": "9e51a0fe-304b-41ed-a0c2-ea773cd4015f", "type": "concept", "title": "public versus private self"}], "description": "The class studies how power, intimacy, history, and social role shape behavior onstage."}, {"id": "8dc61ec2-de20-49fd-b767-6fe96a613260", "type": "subtopic", "title": "Contradiction and change", "children": [{"id": "255d199a-e8e9-4e75-a9fe-0510710e21f9", "type": "concept", "title": "turning points"}, {"id": "229f75e4-8a7f-4b24-b299-60f9bd4c38db", "type": "concept", "title": "revealed values"}, {"id": "bd78695e-156a-41a9-b2eb-5e316cbd92c9", "type": "concept", "title": "character arc"}], "description": "Students learn to avoid flat character summaries by tracking pressure, choice, and transformation."}]}, {"id": "b2945421-d969-4daf-8375-20edf253d721", "type": "topic", "title": "Theme and Meaning", "description": "Students learn to derive meaning from dramatic evidence rather than reducing plays to slogans or moral lessons.", "children": [{"id": "fc166d24-df42-46d8-b186-b125b5420d1d", "type": "subtopic", "title": "Claims supported by evidence", "children": [{"id": "3221d8fb-057e-41e7-a5e5-3a26817c6106", "type": "concept", "title": "textual evidence"}, {"id": "4d2c2f24-73d9-4ee8-a639-69270182806f", "type": "concept", "title": "recurring motifs"}, {"id": "d0635a1c-2dc7-458e-8e7f-bebc4a3e5936", "type": "concept", "title": "argument versus opinion"}], "description": "Students practice building interpretive arguments from scenes, images, choices, and patterns."}, {"id": "234ce613-011a-41bf-96f7-e84543052beb", "type": "subtopic", "title": "Central questions", "children": [{"id": "4441de96-b8e6-4c57-b034-81c364911933", "type": "concept", "title": "guiding question"}, {"id": "1dbf60a7-07ed-4517-ba9e-934c89d554d5", "type": "concept", "title": "conflicting values"}, {"id": "f5a04b78-aab9-4c26-a3b4-f161d6d101b6", "type": "concept", "title": "unresolved tensions"}], "description": "The class identifies the human, political, ethical, or spiritual questions a play keeps testing."}, {"id": "2d93a2e8-157e-420a-b390-ef0b11d0698c", "type": "subtopic", "title": "Audience meaning", "children": [{"id": "c64b36e1-6bd9-4e58-8888-3100de2cd15a", "type": "concept", "title": "audience contract"}, {"id": "d52afe15-459b-4244-a99b-4facb1d79d20", "type": "concept", "title": "reception"}, {"id": "3ec046c4-68d6-4150-9697-d3f638fed3c6", "type": "concept", "title": "ambiguity"}], "description": "Students consider how meaning changes through performance, spectatorship, and cultural context."}]}, {"id": "bc2cf0f3-8753-4a09-90a1-dc85c4ed8989", "type": "topic", "title": "Genre and Style", "description": "This unit helps students recognize the rules, expectations, and performance demands of different dramatic forms.", "children": [{"id": "d40323f7-e2cb-4182-8280-3269f01c5c06", "type": "subtopic", "title": "Genre conventions", "children": [{"id": "e08711ea-2f4b-4843-95b9-51da2198023c", "type": "concept", "title": "comic rhythm"}, {"id": "1f9015f9-36e0-4835-a8db-ccf7aff61bbb", "type": "concept", "title": "tragic action"}, {"id": "f58fa5e3-2fb4-4afd-9eb4-e2db731a71c6", "type": "concept", "title": "documentary ethics"}], "description": "Students compare tragedy, comedy, melodrama, farce, realism, absurdism, and documentary drama."}, {"id": "c0a8342d-2e59-4fb5-a072-ceba9816e496", "type": "subtopic", "title": "Style as performance instruction", "children": [{"id": "7ace9052-f0e1-47fb-a5ca-a1e2ed7e3fd3", "type": "concept", "title": "heightened language"}, {"id": "e4b5f16c-3035-4a5b-ab55-2fc858e78607", "type": "concept", "title": "realist detail"}, {"id": "70f872bd-1679-4ef8-8bc5-e7755ff4ad5f", "type": "concept", "title": "stylized movement"}], "description": "The class studies how language, rhythm, behavior, and staging conventions signal style."}, {"id": "867f2e8f-e57c-452c-bf20-20941e7ceac1", "type": "subtopic", "title": "Mixed and contemporary forms", "children": [{"id": "e1884d79-7bfb-4c24-adb4-59cc443b7b42", "type": "concept", "title": "hybridity"}, {"id": "998ec922-514e-4862-96be-826661277ce7", "type": "concept", "title": "metatheater"}, {"id": "7df5c732-0461-4648-91c0-673beb987552", "type": "concept", "title": "postdramatic elements"}], "description": "Students examine plays that blend genres or challenge inherited categories."}]}, {"id": "3619f333-9792-4ace-b4c4-4d974fe4bb78", "type": "topic", "title": "Given Circumstances", "description": "Students learn to collect the factual conditions that make a play's behavior specific, credible, and stageable.", "children": [{"id": "fc806aa4-76cd-4da4-b667-9a4ecc13119e", "type": "subtopic", "title": "Time, place, and situation", "children": [{"id": "ac2b8ef5-012c-4824-a118-da6f2b96bc5e", "type": "concept", "title": "historical moment"}, {"id": "a700fce9-6827-4295-be1b-bf0e0b456f5c", "type": "concept", "title": "location"}, {"id": "e3b1b41c-160e-4293-bf4e-80c3e34fd5c6", "type": "concept", "title": "immediate situation"}], "description": "Students identify the concrete world surrounding each scene and its effect on choices."}, {"id": "300859d0-8bfb-40a1-853d-cdd3f13b2612", "type": "subtopic", "title": "Social and material conditions", "children": [{"id": "997d6de3-67e5-4148-adad-7da32d15c8a6", "type": "concept", "title": "class markers"}, {"id": "9250d702-c854-4d11-8834-0cbd3f753fc8", "type": "concept", "title": "institutions"}, {"id": "e844031a-c2c8-4998-bcb8-9138975c295f", "type": "concept", "title": "resources and scarcity"}], "description": "The class studies class, labor, family, law, religion, technology, and economics as dramatic pressures."}, {"id": "8beb4311-b310-4e5b-b49c-e12e43ef5496", "type": "subtopic", "title": "Rules of the world", "children": [{"id": "b6c0b9f0-b99e-4410-82d6-dacbde6d6dd6", "type": "concept", "title": "world rules"}, {"id": "17023453-400e-42a9-8461-3489dce7a56c", "type": "concept", "title": "offstage world"}, {"id": "e7b6b44f-ee28-474b-9861-e735b888ffc8", "type": "concept", "title": "consequences"}], "description": "Students clarify what is normal, forbidden, possible, or dangerous inside the play."}]}, {"id": "67f71a63-448b-4df6-9ea9-b19ae7fb41b7", "type": "topic", "title": "Dramatic Action", "description": "This unit develops the practical skill of naming what characters do to one another moment by moment.", "children": [{"id": "c9fdb2d7-926a-458e-8295-f79775b0fde6", "type": "subtopic", "title": "Action verbs", "children": [{"id": "9e9d4464-a642-4358-ac35-0326bfa695e7", "type": "concept", "title": "to persuade"}, {"id": "c846257e-1027-4bae-ac0d-491cdcf54563", "type": "concept", "title": "to threaten"}, {"id": "2210e4d0-dc59-4589-82c7-88272459ca69", "type": "concept", "title": "to seduce"}], "description": "Students translate interpretation into playable verbs useful for actors and directors."}, {"id": "85f1355b-2235-4842-8e56-3eb871c50232", "type": "subtopic", "title": "Conflict and tactics", "children": [{"id": "167bde82-a7bc-47d4-9ee0-a638909139cc", "type": "concept", "title": "tactic shifts"}, {"id": "a3216e52-93df-4a07-9c36-951d8c0444e5", "type": "concept", "title": "counteraction"}, {"id": "8861e1f0-6010-4f82-9f5e-e77995c12b33", "type": "concept", "title": "escalation"}], "description": "The class tracks how characters change strategies as obstacles intensify."}, {"id": "fd84df62-f835-4f6d-aa30-6fc64fca0a6f", "type": "subtopic", "title": "Event analysis", "children": [{"id": "6a7d8122-183b-4f28-a85f-f19331f2d688", "type": "concept", "title": "before and after"}, {"id": "bc7ff44d-1f2a-4762-8452-3f30834b5351", "type": "concept", "title": "point of no return"}, {"id": "9b869187-ffbc-41d4-9fbb-7c976494515f", "type": "concept", "title": "new balance of power"}], "description": "Students distinguish talk from action by identifying the event that changes the room."}]}, {"id": "8ab3d746-a727-4a40-84e5-8d490be3f024", "type": "topic", "title": "The World of the Play", "description": "Students synthesize design, dramaturgy, language, space, and social order into a coherent theatrical world.", "children": [{"id": "49995e33-d847-4041-aa2d-28798e026849", "type": "subtopic", "title": "Spatial imagination", "children": [{"id": "c699c761-4946-4c64-95fd-f023f07f377e", "type": "concept", "title": "thresholds"}, {"id": "adbaed3f-0156-4ea5-9b20-372fb4d6d4f6", "type": "concept", "title": "public/private space"}, {"id": "c9c5b670-80bd-4af9-abcb-c643b582611f", "type": "concept", "title": "offstage spaces"}], "description": "Students read for rooms, thresholds, distance, geography, and the politics of space."}, {"id": "d41ca79c-1590-4140-8a8b-1afa803a51d2", "type": "subtopic", "title": "Image, sound, and object systems", "children": [{"id": "3f7498c7-b01e-4bdd-86c0-a19a9cfba0e6", "type": "concept", "title": "objects"}, {"id": "5b5f22c5-4472-4a17-a838-ae52bb70c1e5", "type": "concept", "title": "music and sound"}, {"id": "454b755f-31e9-4b48-9d98-773cb852ae88", "type": "concept", "title": "visual motifs"}], "description": "The class identifies recurring sensory patterns that can guide design and staging."}, {"id": "875a453e-2ca1-4f15-9683-1dda83427999", "type": "subtopic", "title": "Cultural and ethical context", "children": [{"id": "c1a940f1-7c7c-4326-a5be-a6ca500a2f17", "type": "concept", "title": "identity context"}, {"id": "c209d07a-ffe7-4c1a-bfb5-58de98fbbdad", "type": "concept", "title": "cultural specificity"}, {"id": "174f91c0-c2f2-43da-b2f0-1646a0e61e7f", "type": "concept", "title": "ethical research"}], "description": "Students analyze representation, power, identity, and historical responsibility within the play's world."}]}, {"id": "fcef5f8c-8677-4bf3-b202-9fe8fd1ebc1e", "type": "topic", "title": "Major Periods of Dramatic Literature", "description": "This survey unit gives students a usable map of dramatic traditions while connecting history to production choices.", "children": [{"id": "c93f8f78-2df4-467e-bf03-8344d2746fd6", "type": "subtopic", "title": "Classical and early modern drama", "children": [{"id": "0503a9c5-e507-4c71-a073-3a0c96fb48bd", "type": "concept", "title": "chorus"}, {"id": "866b7e19-28e4-4368-8f35-fa9c4336fdba", "type": "concept", "title": "verse"}, {"id": "b4b3283f-d872-415e-8838-809f3b383be0", "type": "concept", "title": "public theater"}], "description": "Students study foundational forms and performance conventions from Greek drama through Shakespeare and related traditions."}, {"id": "f76ec54c-8249-4a38-a359-1bd824453908", "type": "subtopic", "title": "Modern drama", "children": [{"id": "b3181f2b-7d40-4640-9b28-39ad3272c1a7", "type": "concept", "title": "Ibsen and Chekhov"}, {"id": "45258f7d-de20-418e-8478-dcc7b7e7e40e", "type": "concept", "title": "Strindberg"}, {"id": "fcafda1d-50ab-4629-9193-b814588316f8", "type": "concept", "title": "expressionist form"}], "description": "The class tracks realism, naturalism, symbolism, expressionism, and modernist experimentation."}, {"id": "b2e9c0cf-9611-436f-9fcc-fd956c6b756e", "type": "subtopic", "title": "Contemporary and global drama", "children": [{"id": "77e74630-e522-49be-a8a2-959546489efe", "type": "concept", "title": "postcolonial drama"}, {"id": "8b35524a-87af-4322-91d8-dd9acf867a8a", "type": "concept", "title": "Black and feminist theater"}, {"id": "611a5215-b3f2-4306-8dd1-684835add610", "type": "concept", "title": "new writing"}], "description": "Students read across late twentieth- and twenty-first-century playwrights, movements, and theatrical cultures."}]}, {"id": "bd9294e7-b91c-4031-94db-79177e8656ab", "type": "topic", "title": "Dramaturgy, Research, and Context", "description": "This unit connects script analysis with research, production support, and responsible interpretation.", "children": [{"id": "142a9e8d-5a91-46a5-aa60-6b1c0c196ef4", "type": "subtopic", "title": "Research methods", "children": [{"id": "73f24d63-c0b6-4a4e-b505-e5111c917634", "type": "concept", "title": "source quality"}, {"id": "be68e272-5d0a-4191-b49a-b1f523de2213", "type": "concept", "title": "annotations"}, {"id": "f9712609-e496-4f12-bf28-7f5fc6d14777", "type": "concept", "title": "research questions"}], "description": "Students learn to use archives, criticism, interviews, historical sources, and production histories responsibly."}, {"id": "48e5e2a1-1595-4c65-bc59-a561eff62aa6", "type": "subtopic", "title": "Dramaturgical packets", "children": [{"id": "76911519-4601-4018-a641-e71e5bf48401", "type": "concept", "title": "glossaries"}, {"id": "e3c4bfa5-3e8c-4fe4-91d5-703c7480ee19", "type": "concept", "title": "timelines"}, {"id": "6b28e7c1-7433-4700-b004-da666a9487dc", "type": "concept", "title": "context notes"}], "description": "The class practices turning research into concise, useful materials for a rehearsal room."}, {"id": "c65af735-93b5-4ffc-828f-25efc51dbe7f", "type": "subtopic", "title": "Interpretive responsibility", "children": [{"id": "896d6ffc-a0dd-4d73-ab89-f0cd81688298", "type": "concept", "title": "translation choices"}, {"id": "414a3464-3bb7-479c-b9e4-a10cf5c76f64", "type": "concept", "title": "representation"}, {"id": "eb7519b7-4054-4812-9d8b-f31a78bfcb51", "type": "concept", "title": "harm-aware analysis"}], "description": "Students consider adaptation, translation, casting, identity, and cultural context as production decisions."}]}, {"id": "566cb615-80b7-4a2a-9d96-722b6b38f860", "type": "topic", "title": "Writing Analysis Papers", "description": "Students learn to turn close reading and production thinking into clear, evidence-based analytical writing.", "children": [{"id": "2482c960-198a-4aad-b7fc-99f4588e4511", "type": "subtopic", "title": "Thesis and structure", "children": [{"id": "8e00b1a4-8e1c-4fd4-bb6c-7c83f13a7a89", "type": "concept", "title": "thesis statements"}, {"id": "5645cf63-c799-4708-9b93-5d6096880b15", "type": "concept", "title": "topic sentences"}, {"id": "da5a6f9f-9bcf-4dbf-87f6-db6cdda43b12", "type": "concept", "title": "paragraph logic"}], "description": "Students develop arguable claims and organize papers around evidence rather than plot summary."}, {"id": "e072ce65-d313-4346-a3f2-05cc5df785e5", "type": "subtopic", "title": "Close reading", "children": [{"id": "08a4bcc0-c68a-4c4b-bbf5-9d9992716abf", "type": "concept", "title": "quotation selection"}, {"id": "8d02841d-31ae-4f73-b061-861bbf18a665", "type": "concept", "title": "line analysis"}, {"id": "c2e4b591-abdd-4d1b-8382-74647aaabe90", "type": "concept", "title": "stage direction evidence"}], "description": "The class practices analyzing language, action, imagery, rhythm, and stage directions in detail."}, {"id": "31c98407-eace-4682-b045-d5ee36c3c3cc", "type": "subtopic", "title": "Production-centered argument", "children": [{"id": "b503534d-5b02-4e56-a540-85ab67572456", "type": "concept", "title": "actor implications"}, {"id": "5f730660-f250-40b5-a4b7-a615765f1ad1", "type": "concept", "title": "director concept"}, {"id": "5da2c568-a0e4-4a7b-a8b8-9e5e7c1ea931", "type": "concept", "title": "design implications"}], "description": "Students connect analysis to choices a theater maker could test in rehearsal or design."}]}, {"id": "f26e7e27-4064-4b8d-b422-9b080918461b", "type": "topic", "title": "Performance, Adaptation, and Comparative Analysis", "description": "This capstone unit asks students to compare scripts with productions and adaptations so analysis remains tied to living theater.", "children": [{"id": "04810d64-60e9-44af-9cf6-8a5ebefcc902", "type": "subtopic", "title": "Script-to-stage comparison", "children": [{"id": "1cdd8322-59a0-4953-bdc2-f05d6c644f1b", "type": "concept", "title": "cuts and additions"}, {"id": "017b320c-8890-431c-93ea-d7acbcda802e", "type": "concept", "title": "blocking choices"}, {"id": "845d1292-3801-4e30-9069-dd310737acae", "type": "concept", "title": "tone shifts"}], "description": "Students compare textual evidence with recorded or live performance choices."}, {"id": "4dfb468d-41d0-40b3-9130-21a49ca7a796", "type": "subtopic", "title": "Adaptation and translation", "children": [{"id": "728a541f-97c8-4813-938f-84a040aeea69", "type": "concept", "title": "translation notes"}, {"id": "6ffa4266-be7c-4763-ac5c-97be9366c230", "type": "concept", "title": "adapted setting"}, {"id": "bc441541-434d-484e-ba78-12dc794ce8da", "type": "concept", "title": "version history"}], "description": "The class studies how different versions reshape context, language, politics, and audience meaning."}, {"id": "9adcc54d-6a85-4e2b-9c94-fc9611611460", "type": "subtopic", "title": "Final analytical presentation", "children": [{"id": "58107abb-01cd-4738-95dc-2801a858e2f6", "type": "concept", "title": "visual evidence"}, {"id": "eae8d37f-22ef-4f02-bfd9-d35062a9b0be", "type": "concept", "title": "oral argument"}, {"id": "a0094673-a7a6-4a2b-a71f-d78a92f3502b", "type": "concept", "title": "Q&A defense"}], "description": "Students present a production concept or dramaturgical argument grounded in the script."}]}], "dbBacked": true}$scajson$::jsonb,
